BEGIN;
LOCK TABLE report_saved_view,report_saved_view_history IN ACCESS EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM report_saved_view) THEN RAISE EXCEPTION 'Refusing to remove retained saved report view evidence' USING ERRCODE='55000'; END IF; END $$;
REVOKE ALL ON FUNCTION refs_report_saved_view_hash(uuid,text,text,text,uuid,jsonb,text),refs_report_saved_view_request_hash(uuid,uuid,uuid,bigint,text,text,uuid,jsonb,text,text),refs_read_report_saved_views(uuid,uuid,integer,timestamptz,uuid),refs_report_saved_view_payload(uuid,uuid,uuid),refs_create_report_saved_view(uuid,uuid,text,text,uuid,jsonb,text,text,text,text),refs_update_report_saved_view(uuid,uuid,uuid,bigint,text,text,uuid,jsonb,text,text,text,text) FROM refs_app;
DROP TRIGGER report_saved_view_protect ON report_saved_view; DROP TRIGGER report_saved_view_history_append_only ON report_saved_view_history; DROP FUNCTION refs_update_report_saved_view(uuid,uuid,uuid,bigint,text,text,uuid,jsonb,text,text,text,text); DROP FUNCTION refs_create_report_saved_view(uuid,uuid,text,text,uuid,jsonb,text,text,text,text); DROP FUNCTION refs_read_report_saved_views(uuid,uuid,integer,timestamptz,uuid); DROP FUNCTION refs_report_saved_view_payload(uuid,uuid,uuid); DROP FUNCTION refs_validate_report_saved_view(uuid,uuid,text,text,uuid,jsonb,text); DROP FUNCTION refs_report_saved_view_request_hash(uuid,uuid,uuid,bigint,text,text,uuid,jsonb,text,text); DROP FUNCTION refs_report_saved_view_hash(uuid,text,text,text,uuid,jsonb,text); DROP FUNCTION refs_guard_report_saved_view(); DROP TABLE report_saved_view_history; DROP TABLE report_saved_view; UPDATE permission_catalog SET active=false,effective_to=clock_timestamp(),version=version+1 WHERE permission_code LIKE 'REPORT.SAVED_VIEW.%'; DELETE FROM runtime_human_permission_authority WHERE permission_code LIKE 'REPORT.SAVED_VIEW.%';
COMMIT;
